# =============================================================================
# registry_environment.R - registry rows for the environmental indicators.
#
# GENERATED by cfi-environdata/python/make_registry.py. Do not edit by hand
# there or here; edit the generator, which validates that every column of
# all_indicators.csv is either registered or explicitly excluded.
#
# Source data: cfi-environdata/data/output/all_indicators.csv, produced by a
# Python + Google Earth Engine pipeline that samples remote-sensing rasters at
# each listed business's coordinates. Column-level detail, provenance and
# caveats: that repo's data/output/data_dictionary.md.
#
# FRAME. These attach to the ENUMERATION frame: the GSMM listing is the census
# of business locations, so every listed business has coordinates whether or
# not it was selected or interviewed. They reach all_data through the existing
# GSMM linkage (prep_cto.R records gsmm_business_id).
#
# ID CONVENTION - A DELIBERATE DEVIATION. Enumeration-frame ids in registry.R
# are prefixed `enum_`. These are not, because the id must match the column name
# in all_indicators.csv, which is fixed by the producing pipeline and its data
# dictionary. Renaming on import would work but would break that correspondence.
# Worth a decision before merging.
#
# JOIN. On country + enterprise_id, NOT enterprise_id alone: GSMM ids are unique
# only within a country (5 collide across countries in the five-city frame).
# The source file's business_id is already "<Country>_<EnterpriseID>".
#
# NOT REGISTERED (and why):
#   business_id            join key
#   enterprise_id          join key (with country)
#   country                join key (with enterprise_id)
#   city                   already a GROUPS entry in registry.R
#   latitude               SENSITIVE - exact business location, must not reach enum_data
#   longitude              SENSITIVE - exact business location, must not reach enum_data
#   fieldwork_date         listing date; already on enum_data
#   heat_window_start      constant provenance metadata
#   heat_window_end        constant provenance metadata
#   rain_window_start      constant provenance metadata
#   rain_window_end        constant provenance metadata
#   aod_window_start       constant provenance metadata
#   aod_window_end         constant provenance metadata
#   pop_year               constant provenance metadata (WorldPop vintage)
#
# latitude/longitude are excluded as SENSITIVE. They must never reach
# enum_snapshot.rds, which is committed and shipped to the deployed app. Only
# the derived indicators below are safe: they describe the neighbourhood, not
# the address.
#
# TO USE: source this file after registry.R and bind the rows, e.g.
#   REGISTRY <- bind_rows(REGISTRY, REGISTRY_ENVIRONMENT)
# =============================================================================

REGISTRY_ENVIRONMENT <- tribble(
  ~id, ~label, ~domain, ~type, ~source_q, ~source_col, ~notes, ~description,
  "elevation_m", "Elevation (m)", "env_terrain", "continuous", NA, "elevation_m", "GEE: USGS/SRTMGL1_003", "Metres above sea level at the business location, sampled from SRTM 30m (2000 vintage). Feeds the coastal_lowland flag. Differs sharply between cities by construction - Addis Ababa sits above 2,000m, Sao Paulo around 772m and Delhi around 225m, while Lagos and Jakarta are near sea level - so it is a geography control, not a finding.",
  "slope_degrees", "Terrain slope (degrees)", "env_terrain", "continuous", NA, "slope_degrees", "Derived: ee.Terrain.slope on USGS/SRTMGL1_003", "Terrain slope in degrees at the business location. A landslide-susceptibility proxy - the survey asks about clim_event_landslide and clim_damage_landslide, which had no environmental counterpart before - and a surface-runoff term linking terrain to flood exposure. City means: Sao Paulo 5.2, Addis Ababa 3.9, Lagos 2.9, Delhi 2.7, Jakarta 2.6 degrees. Sao Paulo is the steepest of the five - its hilly plateau terrain, not a data artefact.",
  "heat_days_gt40c", "Days above 40C", "env_heat", "continuous", NA, "heat_days_gt40c", "GEE: MODIS/061/MOD11A1 | count over OBSERVED days", "Number of days in a fixed 730-day window where daytime land surface temperature exceeded 40C. NOT COMPARABLE ACROSS CITIES as a raw count: it counts only clear-sky days, and cloud cover makes that denominator range from ~404 observed days in Addis Ababa to ~40 in Lagos (Delhi ~334, Sao Paulo ~235, Jakarta ~86). Use heat_frac_gt40c for any comparison.",
  "heat_frac_gt40c", "Share of observed days above 40C", "env_heat", "continuous", NA, "heat_frac_gt40c", "Derived: heat_days_gt40c / lst_valid_obs", "Share of this location's OBSERVED days whose land surface temperature exceeded 40C, in 0-1. This is the cross-city comparable form of heat_days_gt40c, normalising away the 10x difference in clear-sky observation counts between cities. Missing where no valid observations exist, never zero.",
  "heat_days_gt45c", "Days above 45C", "env_heat", "continuous", NA, "heat_days_gt45c", "GEE: MODIS/061/MOD11A1 | count over OBSERVED days", "As heat_days_gt40c at a 45C threshold. Not comparable across cities as a raw count; use heat_frac_gt45c.",
  "heat_frac_gt45c", "Share of observed days above 45C", "env_heat", "continuous", NA, "heat_frac_gt45c", "Derived: heat_days_gt45c / lst_valid_obs", "Share of observed days exceeding 45C land surface temperature, in 0-1. Cross-city comparable form of heat_days_gt45c.",
  "heat_days_gt50c", "Days above 50C", "env_heat", "continuous", NA, "heat_days_gt50c", "GEE: MODIS/061/MOD11A1 | count over OBSERVED days", "As heat_days_gt40c at a 50C threshold. Very rare in these cities - near zero almost everywhere - so it will not support a subgroup analysis. Use heat_frac_gt50c for comparison.",
  "heat_frac_gt50c", "Share of observed days above 50C", "env_heat", "continuous", NA, "heat_frac_gt50c", "Derived: heat_days_gt50c / lst_valid_obs", "Share of observed days exceeding 50C land surface temperature, in 0-1. Near zero almost everywhere in these cities.",
  "heat_nights_gt20c", "Nights above 20C", "env_heat", "continuous", NA, "heat_nights_gt20c", "GEE: MODIS/061/MOD11A1 LST_Night_1km | count over OBSERVED nights", "Nights in the 730-day window whose land surface temperature stayed above 20C. NOT COMPARABLE ACROSS CITIES as a raw count - use heat_nights_frac_gt20c. This is the exposure daytime measures miss entirely: Addis Ababa and Lagos are identical on heat_days_gt40c (both zero) yet Lagos averages 152 hot nights and Addis Ababa none, because highland Addis cools at night and coastal Lagos does not. Delhi has the highest raw count at 248, but READ IT AGAINST THE SHARE: its 0.59 is far below Jakarta's 0.99 and Lagos's 0.98, because Delhi's continental winter delivers genuinely cool nights that the tropical coastal cities never see. Sao Paulo is the same story further along: 87 nights, a share of just 0.38, the lowest of any city that records any at all.",
  "heat_nights_frac_gt20c", "Share of observed nights above 20C", "env_heat", "continuous", NA, "heat_nights_frac_gt20c", "Derived: heat_nights_gt20c / lst_night_valid_obs", "Share of this location's OBSERVED nights above 20C land surface temperature, in 0-1. The cross-city comparable form of heat_nights_gt20c.",
  "heat_nights_gt25c", "Nights above 25C", "env_heat", "continuous", NA, "heat_nights_gt25c", "GEE: MODIS/061/MOD11A1 LST_Night_1km | count over OBSERVED nights", "Nights above 25C land surface temperature - the stricter no-recovery threshold. Not comparable across cities as a raw count; use heat_nights_frac_gt25c.",
  "heat_nights_frac_gt25c", "Share of observed nights above 25C", "env_heat", "continuous", NA, "heat_nights_frac_gt25c", "Derived: heat_nights_gt25c / lst_night_valid_obs", "Share of observed nights above 25C, in 0-1. Cross-city comparable.",
  "lst_night_mean_c", "Mean night land surface temperature (C)", "env_heat", "continuous", NA, "lst_night_mean_c", "GEE: MODIS/061/MOD11A1 LST_Night_1km", "Mean NIGHT-TIME land surface temperature. Nights that stay hot deny physiological recovery, which tracks heat morbidity better than daytime peaks. City means: Jakarta 25.6C, Lagos 24.7C, Delhi 21.5C, Sao Paulo 18.3C, Addis Ababa 12.8C. Needs no observation-count normalisation.",
  "lst_night_min_c", "Coolest night land surface temperature (C)", "env_heat", "continuous", NA, "lst_night_min_c", "GEE: MODIS/061/MOD11A1 LST_Night_1km", "Coolest night-time land surface temperature observed in the window. Reaches -4.7C on average in highland Addis Ababa, 6.1C in subtropical Sao Paulo and 7.6C in continental Delhi, against 19.9C in Jakarta.",
  "lst_night_valid_obs", "Clear-sky observations (night LST)", "env_heat", "continuous", NA, "lst_night_valid_obs", "Diagnostic, not a substantive indicator", "Clear-sky night-time MODIS observations in the window, of 730 possible. DATA QUALITY DIAGNOSTIC and the denominator behind the heat_nights_frac_* columns. City means: Delhi 419, Addis Ababa 373, Sao Paulo 226, Lagos 154, Jakarta 78.",
  "lst_mean_c", "Mean land surface temperature (C)", "env_heat", "continuous", NA, "lst_mean_c", "GEE: MODIS/061/MOD11A1", "Mean daytime LAND SURFACE temperature in Celsius over a fixed 730-day window. This is the radiative temperature of the ground, not air temperature: in built-up areas it runs 10-20C above what a weather station would report, which is what makes it useful for localised heat exposure. Terra overpasses around 10:30 local solar time, so it is mid-morning surface heat, not the afternoon peak. Unlike the day-counts, this is comparable across cities.",
  "lst_max_c", "Maximum land surface temperature (C)", "env_heat", "continuous", NA, "lst_max_c", "GEE: MODIS/061/MOD11A1", "Highest daytime land surface temperature observed in the 730-day window. Biased downward where clear-sky coverage is sparse (Lagos, Jakarta), since fewer observations means fewer chances to catch an extreme.",
  "lst_valid_obs", "Clear-sky observations (LST)", "env_heat", "continuous", NA, "lst_valid_obs", "Diagnostic, not a substantive indicator", "Number of clear-sky MODIS observations at this location within the 730-day window, of 730 possible. DATA QUALITY DIAGNOSTIC - its mean is not a finding. It is the denominator behind every heat_frac_* column and the reason raw heat day-counts cannot be compared across cities: city means run ~404 (Addis Ababa), ~334 (Delhi), ~235 (Sao Paulo), ~86 (Jakarta), ~40 (Lagos). Use it to filter low-coverage locations.",
  "hand_m", "Height above nearest drainage (m)", "env_flood", "continuous", NA, "hand_m", "GEE: MERIT/Hydro/v1_0_1", "Vertical distance in metres from the business to the nearest stream channel along the hydrological flow path. Lower means more flood-susceptible. A topographic proxy, not a flood model: it knows nothing about drainage infrastructure, levees or rainfall-driven pluvial flooding.",
  "hand_flood_vulnerable", "Flood-vulnerable location", "env_flood", "binary", NA, "hand_flood_vulnerable", "Derived: hand_m <= 5m", "Business sits within 5 metres above the nearest drainage channel, the standard floodplain proxy. Discriminates poorly in flat coastal cities where most of the urban area qualifies - it is TRUE for about 87% of Lagos businesses - so it separates cities better than it separates businesses within one.",
  "jrc_max_extent", "Ever-observed surface water", "env_flood", "binary", NA, "jrc_max_extent", "GEE: JRC/GSW1_4/GlobalSurfaceWater", "Surface water was detected at this exact location at least once in the 1984-2021 Landsat record. Very rare at business locations (well under 1%), so it identifies a handful of waterside premises rather than supporting a subgroup analysis.",
  "jrc_recurrence", "Water recurrence (%)", "env_flood", "continuous", NA, "jrc_recurrence", "GEE: JRC/GSW1_4/GlobalSurfaceWater | ~99.8% MISSING", "Percentage of months with water detected, 1984-2021. ALMOST ENTIRELY MISSING at business locations (99.9%, only 21 of 24,497) because JRC masks recurrence outside water bodies. The non-missing values are no longer all 100: Delhi and Sao Paulo introduced seasonally-wet locations recording 20-76, so the column now mixes permanent and intermittent water. Still not usable as a continuous variable at this sample size - prefer jrc_max_extent, and do not impute its missingness.",
  "coastal_lowland", "Coastal lowland", "env_flood", "binary", NA, "coastal_lowland", "Derived: coastal city AND elevation < 10m", "Business is in a designated coastal city (Lagos or Jakarta) and sits below 10 metres elevation - the standard Low-Elevation Coastal Zone definition, a proxy for storm-surge and tidal exposure. FALSE for every Addis Ababa, Delhi and Sao Paulo business by construction, since the flag is only applied to coastal cities, so never read it as a within-city finding in any of the three.",
  "canopy_fraction_50m", "Tree canopy within 50m", "env_green", "continuous", NA, "canopy_fraction_50m", "GEE: ESA/WorldCover/v200", "Share of land within 50 metres classified as tree cover, in 0-1. Very low at business locations across all five cities (city means 0.3% in Lagos to 4.2% in Delhi), so it is heavily right-skewed and a mean will be dominated by a few green outliers.",
  "canopy_fraction_150m", "Tree canopy within 150m", "env_green", "continuous", NA, "canopy_fraction_150m", "GEE: ESA/WorldCover/v200", "Share of land within 150 metres classified as tree cover, in 0-1. The 150m radius matches the MAP2 sampling block size, making this the neighbourhood-scale greenness measure. A proxy for shade and microclimate moderation, not a measurement of shade at the premises.",
  "canopy_pixel_count_50m", "Valid canopy pixels (50m)", "env_green", "continuous", NA, "canopy_pixel_count_50m", "Diagnostic, not a substantive indicator", "Count of valid 10m WorldCover pixels inside the 50m buffer, about 98 when complete. DATA QUALITY DIAGNOSTIC for confirming full buffer coverage.",
  "canopy_pixel_count_150m", "Valid canopy pixels (150m)", "env_green", "continuous", NA, "canopy_pixel_count_150m", "Diagnostic, not a substantive indicator", "Count of valid 10m WorldCover pixels inside the 150m buffer, about 760 when complete. DATA QUALITY DIAGNOSTIC.",
  "canopy_tree_pixels_50m", "Tree pixels (50m)", "env_green", "continuous", NA, "canopy_tree_pixels_50m", "Diagnostic; canopy_fraction_50m is the analysis form", "Count of tree-classified 10m pixels within 50 metres. The numerator of canopy_fraction_50m - use the fraction for analysis.",
  "canopy_tree_pixels_150m", "Tree pixels (150m)", "env_green", "continuous", NA, "canopy_tree_pixels_150m", "Diagnostic; canopy_fraction_150m is the analysis form", "Count of tree-classified 10m pixels within 150 metres. The numerator of canopy_fraction_150m - use the fraction for analysis.",
  "rain_days_gt20mm", "Heavy rain days (>20mm)", "env_rain", "continuous", NA, "rain_days_gt20mm", "GEE: UCSB-CHC/CHIRPS/V3/DAILY_SAT", "Days in a fixed 730-day window with more than 20mm of rainfall. UNLIKE the heat and air-quality day-counts this IS directly comparable across cities: CHIRPS is gap-filled rather than cloud-masked, so every location has all 730 days observed. At 5.5km resolution it varies almost entirely between cities, not within them.",
  "rain_days_gt50mm", "Very heavy rain days (>50mm)", "env_rain", "continuous", NA, "rain_days_gt50mm", "GEE: UCSB-CHC/CHIRPS/V3/DAILY_SAT", "Days in the 730-day window exceeding 50mm of rainfall, a threshold commonly associated with urban flood events. Directly comparable across cities. Near zero in Addis Ababa and Sao Paulo, which almost never see daily totals that high, and only ~1 day in Delhi, whose monsoon is intense but short.",
  "rain_total_mm", "Total rainfall (mm)", "env_rain", "continuous", NA, "rain_total_mm", "GEE: UCSB-CHC/CHIRPS/V3/DAILY_SAT", "Total accumulated precipitation over the fixed 730-day window. Halve it for an annual figure. Varies almost entirely between cities at 5.5km resolution.",
  "rain_max_day_mm", "Wettest day (mm)", "env_rain", "continuous", NA, "rain_max_day_mm", "GEE: UCSB-CHC/CHIRPS/V3/DAILY_SAT", "Highest single-day rainfall in the 730-day window - the extreme-event measure rather than the accumulation.",
  "rain_mean_daily_mm", "Mean daily rainfall (mm)", "env_rain", "continuous", NA, "rain_mean_daily_mm", "GEE: UCSB-CHC/CHIRPS/V3/DAILY_SAT", "Mean daily precipitation over the 730-day window. A linear rescaling of rain_total_mm, so it carries no additional information.",
  "rain_days_dry", "Dry days (<1mm)", "env_rain", "continuous", NA, "rain_days_dry", "GEE: CHIRPS | WMO dry-day threshold | RECOMMENDED over rain_days_zero", "Days in the fixed 730-day window with rainfall below 1mm, the WMO convention for a day without meaningful rain. Directly comparable across cities (CHIRPS is gap-filled, so every location has all 730 days). PREFER THIS TO rain_days_zero: CHIRPS is an interpolated satellite/gauge blend, so an exact 0.0mm is partly an artefact of the interpolation, and the two measures REVERSE the city ranking - Addis Ababa has ~320 days between 0 and 1mm that the zero count discards, putting it last on zeros and near-first here. City means: Delhi 571, Sao Paulo 487, Lagos 433, Addis Ababa 412, Jakarta 249.",
  "rain_frac_dry", "Share of days dry (<1mm)", "env_rain", "continuous", NA, "rain_frac_dry", "Derived: rain_days_dry / rain_valid_obs", "Share of the window's days with rainfall below 1mm, in 0-1. An exact rescale of rain_days_dry (rain_valid_obs is a constant 730), provided because a share is the natural way to read a dry-day measure. City means: Delhi 0.78, Sao Paulo 0.67, Lagos 0.59, Addis Ababa 0.56, Jakarta 0.34.",
  "rain_days_zero", "Days with exactly zero rainfall", "env_rain", "continuous", NA, "rain_days_zero", "GEE: CHIRPS | literal zero; prefer rain_days_dry", "Days recorded as exactly 0.0mm. The literal reading of 'no rainfall', retained as a sensitivity check, but rain_days_dry is the defensible measure - see its description for why the two disagree and reverse the city ranking. City means: Delhi 381, Sao Paulo 318, Lagos 233, Jakarta 127, Addis Ababa 91.",
  "rain_frac_zero", "Share of days with zero rainfall", "env_rain", "continuous", NA, "rain_frac_zero", "Derived: rain_days_zero / rain_valid_obs", "Share of the window's days recorded as exactly 0.0mm, in 0-1. Sensitivity check on rain_frac_dry.",
  "rain_max_dry_spell", "Longest dry spell (days)", "env_rain", "continuous", NA, "rain_max_dry_spell", "GEE: CHIRPS | running streak via ee.ImageCollection.iterate", "Longest run of CONSECUTIVE days below 1mm in the window. A MATERIALLY DIFFERENT HAZARD from the dry-day total, and the measure that speaks to the survey's clim_event_drought and clim_damage_drought items: Lagos and Addis Ababa have almost the same dry-day counts (433 vs 412) but very different spells (58 vs 86 days, reaching 133 in Addis Ababa), because Lagos spreads its dry days across a bimodal regime while Addis Ababa concentrates them into one long dry season. Delhi is the extreme case on both measures - 571 dry days AND the longest spells (mean 91, reaching 152) - a single monsoon burst against a long dry remainder. Sao Paulo is the clearest counter-example: second-highest dry-day count at 487 but the SHORTEST spells of all five (mean 30), because its dry days are scattered through the year rather than massed into a season. The two columns must therefore be read together - the dry-day count alone would rank Sao Paulo as drought-exposed, and the spell says otherwise. Within-city variation is real but VERY UNEVEN: Addis Ababa SD 23.7 days against Delhi's 3.9 and Sao Paulo's 0.5, so this supports within-city analysis in Addis Ababa and essentially none in Delhi or Sao Paulo. CAVEAT: spells are truncated at the window edges, so a dry period already underway at the start or still running at the end is cut off and the true maximum can be longer.",
  "rain_valid_obs", "Days with rainfall data", "env_rain", "continuous", NA, "rain_valid_obs", "Diagnostic, not a substantive indicator", "Days with valid CHIRPS data in the window. Exactly 730 for every location because CHIRPS is gap-filled - which is precisely why the rainfall day-counts need no normalisation, unlike heat and AOD. DATA QUALITY DIAGNOSTIC with no variance.",
  "aod_days_gt0p4", "Days AOD above 0.4", "env_air", "continuous", NA, "aod_days_gt0p4", "GEE: MODIS/061/MCD19A2_GRANULES | count over OBSERVED days", "Days in the 730-day window with aerosol optical depth above 0.4 (roughly PM2.5 ~35 ug/m3). NOT COMPARABLE ACROSS CITIES as a raw count, and the error is not subtle: ranking cities on this puts Lagos LAST for pollution, while the observation-normalised rate puts it FIRST. Use aod_frac_gt0p4.",
  "aod_frac_gt0p4", "Share of observed days AOD above 0.4", "env_air", "continuous", NA, "aod_frac_gt0p4", "Derived: aod_days_gt0p4 / aod_valid_obs", "Share of this location's OBSERVED days with AOD above 0.4, in 0-1. The cross-city comparable form: city means are Delhi 77%, Lagos 77%, Jakarta 57%, Addis Ababa 26%, Sao Paulo 10%, a ranking corroborated by aod_mean and the reverse of what raw day-counts suggest. Delhi ties Lagos on this share but has the highest aod_mean (0.77 vs 0.65), so it is the most polluted of the five on the continuous measure; Sao Paulo is the cleanest by a wide margin (aod_mean 0.21). NOTE Sao Paulo is simultaneously the WORST city on no2_mean (163) - see that column.",
  "aod_days_gt0p8", "Days AOD above 0.8", "env_air", "continuous", NA, "aod_days_gt0p8", "GEE: MODIS/061/MCD19A2_GRANULES | count over OBSERVED days", "Days with AOD above 0.8 (high pollution, roughly PM2.5 ~70 ug/m3). Not comparable across cities as a raw count; use aod_frac_gt0p8.",
  "aod_frac_gt0p8", "Share of observed days AOD above 0.8", "env_air", "continuous", NA, "aod_frac_gt0p8", "Derived: aod_days_gt0p8 / aod_valid_obs", "Share of observed days with AOD above 0.8, in 0-1. Cross-city comparable form of aod_days_gt0p8.",
  "aod_days_gt1p5", "Days AOD above 1.5", "env_air", "continuous", NA, "aod_days_gt1p5", "GEE: MODIS/061/MCD19A2_GRANULES | count over OBSERVED days", "Days with AOD above 1.5 (very high / hazardous, roughly PM2.5 ~130 ug/m3). Rare outside Lagos. Not comparable across cities as a raw count; use aod_frac_gt1p5.",
  "aod_frac_gt1p5", "Share of observed days AOD above 1.5", "env_air", "continuous", NA, "aod_frac_gt1p5", "Derived: aod_days_gt1p5 / aod_valid_obs", "Share of observed days with AOD above 1.5, in 0-1. Cross-city comparable form of aod_days_gt1p5.",
  "aod_mean", "Mean aerosol optical depth", "env_air", "continuous", NA, "aod_mean", "GEE: MODIS/061/MCD19A2_GRANULES", "Mean aerosol optical depth at 470nm over the 730-day window - the most widely used satellite proxy for ground-level PM2.5. Needs no observation-count normalisation, so it is the safest air-quality measure for cross-city comparison. Read it as a relative exposure ranking, not an absolute PM2.5 estimate: the AOD-to-PM2.5 relationship shifts with humidity, aerosol type and boundary layer height.",
  "aod_max", "Maximum aerosol optical depth", "env_air", "continuous", NA, "aod_max", "GEE: MODIS/061/MCD19A2_GRANULES", "Highest AOD observed in the window - the pollution-episode measure. Biased downward where clear-sky retrievals are sparse.",
  "aod_median", "Median aerosol optical depth", "env_air", "continuous", NA, "aod_median", "GEE: MODIS/061/MCD19A2_GRANULES", "Median AOD over the window, less sensitive than the mean to a few severe pollution episodes. Prefer it to aod_mean when the question is about typical conditions rather than including extremes.",
  "aod_valid_obs", "Clear-sky observations (AOD)", "env_air", "continuous", NA, "aod_valid_obs", "Diagnostic, not a substantive indicator", "Number of days with a valid AOD retrieval in the 730-day window. DATA QUALITY DIAGNOSTIC - its mean is not a finding. It is the denominator behind every aod_frac_* column; city means run ~647 (Delhi), ~357 (Sao Paulo), ~347 (Addis Ababa), ~201 (Jakarta), ~90 (Lagos). Delhi's dry, clear climate yields nearly its full window, which is exactly why its RAW day-counts dwarf every other city's and must not be compared directly.",
  "ntl_mean_radiance", "Mean nighttime radiance", "env_light", "continuous", NA, "ntl_mean_radiance", "GEE: NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG", "Mean nighttime light radiance (nW/cm2/sr) within 150 metres, averaged over 12 monthly composites. A well-established proxy for economic activity and infrastructure density at the NEIGHBOURHOOD level - it is not a measure of this business's revenue or activity, and should be used as a context control rather than an outcome.",
  "ntl_median_radiance", "Median nighttime radiance", "env_light", "continuous", NA, "ntl_median_radiance", "GEE: NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG", "Median monthly nighttime radiance within 150 metres over 12 months, less sensitive than the mean to one unusual month such as a festival or construction lighting.",
  "ntl_max_radiance", "Maximum nighttime radiance", "env_light", "continuous", NA, "ntl_max_radiance", "GEE: NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG", "Brightest monthly composite within 150 metres over the 12-month window. In Lagos, gas flaring can inflate this in some areas - a real feature of the economic landscape, but worth knowing when interpreting high outliers.",
  "ntl_sd_radiance", "Nighttime radiance SD", "env_light", "continuous", NA, "ntl_sd_radiance", "Derived: SD across 12 monthly VIIRS composites", "Standard deviation of nighttime radiance across the 12 monthly composites. Use ntl_cv_radiance instead when comparing locations of different brightness.",
  "ntl_cv_radiance", "Nighttime radiance variability (CV)", "env_light", "continuous", NA, "ntl_cv_radiance", "Derived: ntl_sd_radiance / ntl_mean_radiance | WEAK outage proxy", "Coefficient of variation of monthly nighttime radiance, so dim and bright locations are comparable. Added with the survey's clim_adapt_generator item in mind, but READ IT CAUTIOUSLY: VIIRS composites are MONTHLY, so an outage lasting hours or days is averaged away and leaves no trace. It measures month-to-month lighting instability, mixing sustained grid problems with seasonal and economic change. Suggestive of reliability, not a measurement of outage frequency; daily VIIRS (NOAA/VIIRS/DNB/VNP46A2) would be needed for that. City means: Jakarta 0.57, Lagos 0.30, Addis Ababa 0.28, Delhi 0.18, Sao Paulo 0.11.",
  "builtup_fraction_50m", "Built-up surface within 50m", "env_built", "continuous", NA, "builtup_fraction_50m", "GEE: JRC/GHSL/P2023A/GHS_BUILT_S/2020", "Share of land within 50 metres covered by built structures, in 0-1, from GHSL 10m (2020 epoch). Near-inverse of canopy_fraction_50m in urban settings.",
  "builtup_fraction_150m", "Built-up surface within 150m", "env_built", "continuous", NA, "builtup_fraction_150m", "GEE: JRC/GHSL/P2023A/GHS_BUILT_S/2020", "Share of land within 150 metres covered by built structures, in 0-1. A primary driver of the urban heat island and of stormwater runoff, so it links the heat and flood indicators. NOTE it is correlated with pop_density_150m (r = 0.41), which is partly by construction since WorldPop uses built-up surface as a covariate; it is effectively uncorrelated with hrsl_density_150m (r = -0.05).",
  "pop_density_50m", "Population density within 50m (WorldPop)", "env_pop", "continuous", NA, "pop_density_50m", "GEE: WorldPop/GP/100m/pop, 2020 | sub-pixel", "Residents per square kilometre within 50 metres, from WorldPop 100m (2020). SUB-PIXEL: a 50m buffer is smaller than one ~93m WorldPop cell, so this is effectively the containing cell's value and correlates with pop_density_150m at r = 0.9987. Prefer the 150m column, which also has fewer missing values.",
  "pop_density_150m", "Population density within 150m (WorldPop)", "env_pop", "continuous", NA, "pop_density_150m", "GEE: WorldPop/GP/100m/pop, 2020 | see hrsl_density_150m", "Residents per square kilometre within 150 metres, from WorldPop 100m (2020). RESIDENTIAL population - it disaggregates census counts, i.e. where people sleep - so it understates commercial districts with heavy daytime footfall. Missing for 28 businesses on the North Jakarta coast where WorldPop's land mask excludes settled land; do NOT impute those as zero, and note hrsl_density_150m covers them. Disagrees substantially with hrsl_density_150m on level (Addis Ababa 12,314 vs 26,443; Delhi 27,288 vs 66,336 - a factor of 2.4) while ranking neighbourhoods similarly within a city (r = 0.73-0.95, lowest in Lagos), so treat absolute and cross-city density claims with caution. Sao Paulo is the one city where the two nearly agree (18,174 vs 20,802), which is a caution in itself: agreement is not a property of the products, it varies by city.",
  "hrsl_density_50m", "Population density within 50m (Meta HRSL)", "env_pop", "continuous", NA, "hrsl_density_50m", "Community GEE asset: projects/sat-io/open-datasets/hrsl/hrslpop", "Residents per square kilometre within 50 metres, from Meta's High Resolution Settlement Layer (~31m, building-footprint constrained). Despite the finer grid it still correlates with hrsl_density_150m at r = 0.9974 - the redundancy comes from the spatial autocorrelation of population, not pixel size - so prefer the 150m column.",
  "building_count_50m", "Buildings within 50m", "env_built", "continuous", NA, "building_count_50m", "GEE: GOOGLE/Research/open-buildings-temporal/v1, 2023 | INDEX, not a census", "Number of buildings within 50 metres. Largely INDEPENDENT of builtup_fraction_50m (r = +0.17), so it does not restate the built-up indicator: counting discrete structures measures something different from the share of ground they cover. RELATIVE MEASURE ONLY: validated against Open Buildings v3 polygons at r=0.90 but running ~25% HIGH in level, so use it to compare locations, not to state how many buildings are present.",
  "building_count_150m", "Buildings within 150m", "env_built", "continuous", NA, "building_count_150m", "GEE: GOOGLE/Research/open-buildings-temporal/v1, 2023 | INDEX, not a census", "Number of buildings within 150 metres. City means: Jakarta 454, Sao Paulo 399, Delhi 395, Addis Ababa 394, Lagos 347 - strikingly flat across five very different cities. Only moderately correlated with builtup_fraction_150m (r = +0.32 raw pooled; +0.54 pooled within city), so it can reasonably enter a model alongside it. RELATIVE MEASURE ONLY - correlates with polygon ground truth at r=0.90 but runs ~25% high in level. Do not quote as an absolute count.",
  "building_height_mean_150m", "Mean building height (m)", "env_built", "continuous", NA, "building_height_mean_150m", "GEE: GOOGLE/Research/open-buildings-temporal/v1, 2023", "Mean height of BUILDINGS within 150 metres, averaged over building pixels only so open ground does not drag it toward zero. THE ONLY VERTICAL MEASURE in this pipeline - built-up fraction, canopy and population are all planar - so it carries information none of them do. City means: Sao Paulo 12.7m, Delhi 9.6m, Addis Ababa 7.5m, Jakarta 7.1m, Lagos 6.4m - Sao Paulo is far and away the tallest, 33% above Delhi and double Lagos, which is what a verticalised Latin American city looks like against five-city company. Since building count is nearly flat across cities (347-454), height is where Sao Paulo's built form actually differs, and a planar measure like builtup_fraction cannot see it. Slightly NEGATIVELY correlated with builtup_fraction_150m (r = -0.15): the most densely covered ground here tends to carry lower buildings.",
  "building_mean_area_150m", "Typical building footprint (m2)", "env_built", "continuous", NA, "building_mean_area_150m", "Derived: built area / building count | INDEX, not a measurement", "Typical building footprint within 150 metres. Together with building count this separates one large structure from many small ones, which builtup_fraction cannot: the five cities sit between 31% and 57% built-up, yet footprints run Addis Ababa 64 m2, Delhi 76, Sao Paulo 78, Jakarta 83, Lagos 92 - a plausible signature of small-plot informal development in Addis Ababa and Delhi. RELATIVE MEASURE ONLY: correlates with polygon ground truth at r=0.85 and preserves the city rank order exactly, but runs ~37% LOW in level (polygons give 91/125/151 m2 for the same buffers). Compare locations with it; do not quote the value as a measured footprint. Missing where the buffer contains no buildings - undefined, not zero.",
  "heat_exposure_index", "Heat exposure index (within-city)", "env_heat", "continuous", NA, "heat_exposure_index", "Derived: mean of signed within-city z-scores | NOT comparable across cities", "Composite within-city heat exposure: the mean of signed z-scores of lst_mean_c, lst_max_c, builtup_fraction_150m and minus canopy_fraction_150m, each standardised WITHIN city. Zero is the city average and +1 is one standard deviation more exposed than other businesses IN THE SAME CITY. LEVELS ARE NOT COMPARABLE ACROSS CITIES - every city has mean zero by construction, so 0.8 means the same thing in Delhi and Addis Ababa and says nothing about which city is hotter. For between-city heat use wbgt_days_gt31c, which integrates temperature and humidity. Standardising within city is deliberate: the humid-heat and night-heat variables have almost no within-city variance (wbgt_days_gt31c 3%, lst_night_mean_c 2%, heat_nights_frac_gt20c 0%), so pooling them would produce a city fixed effect in disguise. Correlates with its components as designed (lst_mean_c +0.74, lst_max_c +0.73, canopy -0.72, builtup +0.58, pooled within city). ITS CONVERGENT VALIDATION IS NOT UNIFORM AND FAILS IN ONE CITY. Against night land surface temperature - deliberately not a component - it runs Addis Ababa +0.62, Lagos +0.51, Delhi +0.38, Jakarta +0.17 but SAO PAULO -0.25, the only negative, which pulls the pooled figure down to +0.28 from +0.40 on the four-city frame. In Sao Paulo the businesses this index scores as most heat-exposed are, if anything, COOLER at night (top decile 18.0C against the bottom decile's 18.5C), even though the index's own components behave normally there (daytime LST 25.2 to 27.5C, canopy 17.1% to 0.9%). The cause is not established - elevation differs by only 9m between those deciles, so terrain does not explain it. Treat the index as validated in Addis Ababa, Lagos and Delhi, weakly supported in Jakarta, and NOT validated in Sao Paulo - prefer the four components separately there. FOR REGRESSION, prefer the four components separately: a composite imposes equal weights that were not estimated. Its value is descriptive - ranking, targeting, communication. Missing where any component is missing, rather than averaging over a partial set.",
  "t2m_mean_c", "Mean air temperature (C)", "env_heatstress", "continuous", NA, "t2m_mean_c", "GEE: ECMWF/ERA5_LAND/DAILY_AGGR | ~11km, CITY-LEVEL", "Mean daily 2-metre AIR temperature over the 730-day window - distinct from land surface temperature, which is the ground's radiative temperature and runs far hotter. ERA5-Land is an ~11km reanalysis grid, COARSER THAN A CITY, so treat this as a city-level control with only a handful of distinct values per city, not within-city variation. City means: Lagos 27.1C, Jakarta 26.6C, Delhi 24.3C, Sao Paulo 19.5C, Addis Ababa 15.2C.",
  "t2m_max_c", "Maximum air temperature (C)", "env_heatstress", "continuous", NA, "t2m_max_c", "GEE: ECMWF/ERA5_LAND/DAILY_AGGR | ~11km, CITY-LEVEL", "Highest daily maximum 2-metre air temperature in the window. City-level control - see t2m_mean_c on resolution.",
  "rh_mean_pct", "Mean relative humidity (%)", "env_heatstress", "continuous", NA, "rh_mean_pct", "Derived from ERA5-Land temperature and dewpoint", "Mean relative humidity, computed from 2m air temperature and dewpoint via the Magnus formula. The variable that makes heat dangerous: at 83% (Lagos) sweat cannot evaporate, whereas 64% (Addis Ababa and Delhi alike) permits cooling. Sao Paulo is humid at 79.5% but mild at 19.5C air temperature, which is why it records essentially no humid-heat days - humidity alone is not the hazard. Note Delhi pairs that moderate annual mean humidity with much higher air temperature than Addis Ababa (24.3C vs 15.2C), which is why its humid-heat day-counts are high despite the dry annual average. City-level control at ~11km.",
  "wbgt_mean_c", "Mean heat stress index (sWBGT, C)", "env_heatstress", "continuous", NA, "wbgt_mean_c", "Derived: simplified WBGT from ERA5-Land | ~11km, CITY-LEVEL", "Mean simplified Wet Bulb Globe Temperature, the standard occupational heat-stress index, combining air temperature and humidity. An approximation - true WBGT also needs radiation and wind - so read it as a relative index rather than an occupational-safety measurement.",
  "wbgt_max_c", "Maximum heat stress index (sWBGT, C)", "env_heatstress", "continuous", NA, "wbgt_max_c", "Derived: simplified WBGT from ERA5-Land | ~11km, CITY-LEVEL", "Highest daily sWBGT in the window.",
  "wbgt_days_gt28c", "Days above heat-stress threshold 28C", "env_heatstress", "continuous", NA, "wbgt_days_gt28c", "Derived: ISO 7243 high-risk threshold | no normalisation needed", "Days above sWBGT 28C, the ISO 7243 threshold for high risk during heavy work. Needs NO observation-count normalisation, unlike the LST and AOD day-counts: ERA5-Land is a reanalysis with no cloud gaps, so every day of the window is present. Jakarta 722 and Lagos 723 of 730 days; Delhi 330; Sao Paulo 7; Addis Ababa zero.",
  "wbgt_days_gt31c", "Days above heat-stress threshold 31C", "env_heatstress", "continuous", NA, "wbgt_days_gt31c", "Derived: ISO 7243 very-high-risk threshold | no normalisation needed", "Days above sWBGT 31C - ISO 7243 'very high risk, rest breaks advised'. THE HEADLINE HUMID-HEAT MEASURE, and it reorders the cities against surface temperature: Lagos 421 days, Delhi 223, Jakarta 85, Addis Ababa 0, Sao Paulo 0 - even though Lagos has LOWER land surface temperature than Jakarta (29.5C vs 35.1C), and Delhi outranks Jakarta on humid heat while sitting between the two on surface temperature. Sao Paulo records zero despite a mean lst_max_c of 38.1C, hotter at the surface than Addis Ababa or Lagos: its air temperature is simply too mild for the sWBGT threshold. THE TWO CITIES AT ZERO ARE AT ZERO FOR DIFFERENT REASONS - Addis Ababa is dry, Sao Paulo is cool - so neither supports a within-city analysis of this column. Humidity, not heat alone, is what removes the body's ability to cool. Prefer this to the heat_days_gt* columns for any analysis of the survey's clim_heat_* items.",
  "no2_mean", "Mean tropospheric NO2", "env_air", "continuous", NA, "no2_mean", "GEE: COPERNICUS/S5P/OFFL/L3_NO2 | micromol/m2", "Mean tropospheric NO2 column density. Specific to COMBUSTION - vehicles, generators, industry - where aod_mean is total particulate loading mixing traffic with dust, sea salt and biomass haze. The two rank the cities DIFFERENTLY, which is why both are carried: Jakarta is worst on NO2 (127.3) while Lagos is worst on AOD (0.648). A column density, not a surface concentration, so read it as a relative ranking rather than what a person breathes.",
  "no2_max", "Maximum tropospheric NO2", "env_air", "continuous", NA, "no2_max", "GEE: COPERNICUS/S5P/OFFL/L3_NO2 | micromol/m2", "Highest single-observation NO2 column density in the window - the pollution-episode measure.",
  "no2_median", "Median tropospheric NO2", "env_air", "continuous", NA, "no2_median", "GEE: COPERNICUS/S5P/OFFL/L3_NO2 | micromol/m2", "Median NO2 column density, less sensitive than the mean to individual episodes. Prefer it for typical conditions.",
  "no2_valid_obs", "Valid NO2 retrievals", "env_air", "continuous", NA, "no2_valid_obs", "Diagnostic, not a substantive indicator", "Number of valid Sentinel-5P retrievals in the window. DATA QUALITY DIAGNOSTIC - its mean is not a finding. The NO2 summaries are means rather than day-counts, so unlike the AOD day-counts they need no normalisation by this.",
  "hrsl_density_150m", "Population density within 150m (Meta HRSL)", "env_pop", "continuous", NA, "hrsl_density_150m", "Community GEE asset: projects/sat-io/open-datasets/hrsl/hrslpop | PREFERRED population measure", "Residents per square kilometre within 150 metres, from Meta's High Resolution Settlement Layer. THE PREFERRED population indicator: finest resolution (~31m), no missing values, and uncorrelated with builtup_fraction_150m (r = -0.05) so it introduces no collinearity. Population is allocated only to cells where a CNN detected a building, which is why it covers settled North Jakarta coast that WorldPop's land mask misses. Use pop_density_150m as a robustness check - any population result that flips between the two is not robust to source choice. Census vintage is roughly 2015-2020, so it is higher-resolution than WorldPop but not more recent.",
) %>% mutate(frame = "Enumeration")
